const items = $input.all();
const currentMonth = new Date().getMonth();
const currentYear = new Date().getFullYear();

// Filter current month transactions
const monthlyTx = items.filter(item => {
  const d = new Date(item.json.tanggal_transaksi);
  return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
});

// Calculate PPN summary
let totalDPP = 0;  // Dasar Pengenaan Pajak
let totalPPN = 0;  // PPN 11%
let totalPPnBM = 0; // PPnBM if any
let fakturCount = 0;

const fakturData = monthlyTx.map(tx => {
  const dpp = Number(tx.json.dpp || tx.json.subtotal || 0);
  const ppn = Math.round(dpp * 0.11);
  const ppnbm = Number(tx.json.ppnbm || 0);
  totalDPP += dpp;
  totalPPN += ppn;
  totalPPnBM += ppnbm;
  fakturCount++;
  return {
    no_faktur: tx.json.no_faktur || `010.000-${currentYear.toString().slice(-2)}.${String(fakturCount).padStart(8, '0')}`,
    tanggal: tx.json.tanggal_transaksi,
    npwp_pembeli: tx.json.npwp_pembeli || '-',
    nama_pembeli: tx.json.nama_customer,
    alamat_pembeli: tx.json.alamat_customer || '-',
    dpp: dpp,
    ppn: ppn,
    ppnbm: ppnbm,
    total: dpp + ppn + ppnbm,
    kode_jenis: tx.json.kode_jenis_transaksi || '01',
    status: 'belum_upload'
  };
});

return [{
  json: {
    periode: `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}`,
    total_faktur: fakturCount,
    total_dpp: totalDPP,
    total_ppn: totalPPN,
    total_ppnbm: totalPPnBM,
    faktur_list: fakturData
  }
}];

